#!/bin/bash
set -e
echo "Deploying Claude-powered research engine..."
mkdir -p src/lib
echo  | base64 -d > src/lib/research-engine.ts
echo "✓ src/lib/research-engine.ts"
mkdir -p src/app/dashboard
echo  | base64 -d > src/app/dashboard/page.tsx
echo "✓ src/app/dashboard/page.tsx"
git add -A
git commit -m "feat: Claude API with native web_search, Groq fallback"
git push origin main
vercel --prod
echo "✅ Claude engine live!"